/**
 * A discriminated union representing either success or failure.
 *
 * - `{ success: true; value: T }` — an `ok` result carrying a value of type `T`.
 * - `{ success: false; error: E }` — an `err` result carrying an error of type `E`.
 *
 * Narrow on the `success` discriminant to safely access `value` or `error`.
 */
export type Result<T, E> = { success: true; value: T } | { success: false; error: E }

/** Wrap a success value. */
export function ok<T>(value: T): Result<T, never> {
  return { success: true, value }
}

/** Wrap a failure error. */
export function err<E>(error: E): Result<never, E> {
  return { success: false, error }
}

/**
 * Transform the success value with `fn`.
 * Returns the original `Err` unchanged if `result` is a failure.
 * If `fn` throws, the thrown value is captured as an `Err`.
 */
export function map<T, U, E>(result: Result<T, E>, fn: (value: T) => U): Result<U, E> {
  if (!result.success) return result
  try {
    return ok(fn(result.value))
  } catch (e) {
    return err(e as E)
  }
}

/**
 * Chain a fallible operation `fn` onto the success value.
 * Returns the original `Err` unchanged if `result` is a failure.
 * If `fn` throws, the thrown value is captured as an `Err`.
 */
export function flatMap<T, U, E>(
  result: Result<T, E>,
  fn: (value: T) => Result<U, E>,
): Result<U, E> {
  if (!result.success) return result
  try {
    return fn(result.value)
  } catch (e) {
    return err(e as E)
  }
}
